// Support for Raven's actors (raven/trusted/actors.rook): the arena they live in,
// and the jump from the scheduler into an actor's dispatcher.

    .section .text

// void call_dispatch(dispatcher, actor, handler, payload)
//
// Jumps to an actor's dispatcher (generated by Fledgling, see Gen.dispatcher)
// with the arguments it expects: x0 = actor, x1 = handler number, x2 = the address
// of the message's payload words. The dispatcher returns to our caller.
    .global call_dispatch
call_dispatch:
    mov     x16, x0                     // the dispatcher's address
    mov     x0, x1
    mov     x1, x2
    mov     x2, x3
    br      x16

// u64 handler_table_start(void), u64 handler_table_end(void): the table Fledgling
// writes of every handler (see Gen.handler_table), to name one that overran.
    .global handler_table_start
handler_table_start:
    adrp    x0, rook_handler_table
    add     x0, x0, :lo12:rook_handler_table
    ret

    .global handler_table_end
handler_table_end:
    adrp    x0, rook_handler_table_end
    add     x0, x0, :lo12:rook_handler_table_end
    ret

// void irq_init(void): lets the physical timer interrupt the core, and unmasks IRQs.
// The Pi's per-core interrupt controller (ARM local peripherals, 0x40000000) routes
// the non-secure physical timer, bit 1 of CORE0_TIMER_IRQCNTL (0x40000040), to the
// core's IRQ. Only core 0 runs Raven for now (decision 111).
    .global irq_init
irq_init:
    msr     cntp_ctl_el0, xzr           // the timer starts disarmed
    ldr     x0, =0x40000040
    mov     w1, #2                      // nCNTPNSIRQ -> IRQ
    str     w1, [x0]
    msr     daifclr, #2                 // unmask IRQ
    isb
    ret

// void irq_enable_source(u64 line): lets peripheral interrupt `line` (32 to 63) through
// the Pi's interrupt controller (IRQ enable 2, 0x3F00B214).
    .global irq_enable_source
irq_enable_source:
    sub     x0, x0, #32
    mov     w1, #1
    lsl     w1, w1, w0
    ldr     x2, =0x3F00B214
    str     w1, [x2]
    ret

// u64 irq_take_pending(void): the sources that have fired since the last call (bit
// n is line 32 + n), and clears them. IRQs are masked meanwhile, so one landing
// halfway can't be lost.
    .global irq_take_pending
irq_take_pending:
    msr     daifset, #2
    adrp    x1, actor_arena
    add     x1, x1, :lo12:actor_arena
    ldr     x0, [x1, #48]
    str     xzr, [x1, #48]
    msr     daifclr, #2
    ret

// void idle_until_interrupt(void): sleeps until an interrupt arrives, unless one
// already has. Masks IRQs while it looks, because `wfi` wakes for a pending
// interrupt even when it is masked, so none can slip between the look and the sleep.
    .global idle_until_interrupt
idle_until_interrupt:
    msr     daifset, #2
    adrp    x1, actor_arena
    add     x1, x1, :lo12:actor_arena
    ldr     x0, [x1, #48]
    cbnz    x0, 1f
    wfi
1:  msr     daifclr, #2
    ret

// void timer_arm(u64 ticks): interrupt after `ticks` counts of the generic timer.
    .global timer_arm
timer_arm:
    msr     cntp_tval_el0, x0
    mov     x1, #1                      // ENABLE, interrupt not masked
    msr     cntp_ctl_el0, x1
    isb
    ret

// void timer_disarm(void)
    .global timer_disarm
timer_disarm:
    msr     cntp_ctl_el0, xzr
    isb
    ret

// u64 actor_arena_base(void), u64 actor_arena_limit(void): the memory every
// actor, mailbox and Raven's actor tables are carved from.
    .global actor_arena_base
actor_arena_base:
    adrp    x0, actor_arena
    add     x0, x0, :lo12:actor_arena
    ret

    .global actor_arena_limit
actor_arena_limit:
    adrp    x0, actor_arena_end
    add     x0, x0, :lo12:actor_arena_end
    ret

    .section .bss
    .balign 4096
    .global actor_arena                 // vectors.s notes interrupts in its pending word
actor_arena:
    .space  65536                       // 64 KB; zeroed at boot with the rest of .bss
actor_arena_end:
